 private static String imageFor(String n){String q=n.toLowerCase();if(q.contains("fish"))return "https://images.unsplash.com/photo-1516685018646-549d72a3a9b1?auto=format&fit=crop&w=900&q=80";if(q.contains("chicken"))return "https://images.unsplash.com/photo-1532550907401-a500c9a57435?auto=format&fit=crop&w=900&q=80";if(q.contains("oat"))return "https://images.unsplash.com/photo-1517673400267-0251440c45dc?auto=format&fit=crop&w=900&q=80";if(q.contains("egg"))return "https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=900&q=80";if(q.contains("khichdi")||q.contains("dal"))return "https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=900&q=80";return "https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=900&q=80";}
 private record Spec(String name,String desc,String meal,String cuisine,int prep,int cook,int servings,double cal,double protein,double carbs,double fat,double fiber,double sodium,String diff,String diet,String health,String ings,String... goals){}
 private static Spec s(String n,String d,String m,String c,int p,int co,int sv,double cal,double pr,double ca,double f,double fi,double so,String di,String dt,String ht,String in,String...g){return new Spec(n,d,m,c,p,co,sv,cal,pr,ca,f,fi,so,di,dt,ht,in,g);}
